using System.Collections.Generic;
using System.Linq;
using Godot;
using Siege.Presentation.Style;

namespace Siege.Godot;

/// <summary>
/// The ten full-art pieces. PieceStyleTable and FactionTable remain the only type and owner mappings.
/// Load order per silhouette: the cartoon <c>parts/pieces_chibi/&lt;key&gt;.glb</c> generated by
/// <c>tools/blender/chibi_pieces.py</c>, then the hand-built <c>parts/pieces/&lt;key&gt;.tscn</c>;
/// if both fail BoardView uses LowPoly.Piece. Deleting <c>pieces_chibi/</c> restores the .tscn look.
/// </summary>
/// <remarks>
/// The two sources are dressed differently. A glb piece stands straight on the cell inside a thin
/// faction-colored ring (no plinth), carries its emblem at the glb's <c>Anchor_Emblem</c> empty, uses toon materials and
/// draws its <c>Line</c> slot as an inverted-hull outline. A .tscn piece keeps the old plinth, seal
/// and matte materials.
/// </remarks>
internal static class PieceModels
{
    /// <summary>Name of the outline hull node; BoardView skips it when picking and fades it when ghosting.</summary>
    internal const string OutlineName = "Outline";

    private const string AnchorName = "Anchor_Emblem";
    private const string LineSlot = "Line";

    // Scene parts (named "<Slot>_<Part>") are merged once by material slot, so each on-board piece
    // uses only a few shared meshes and its own materials whichever source the parts came from.
    private static readonly Dictionary<PieceSilhouette, PieceTemplate> Templates = new();
    private static readonly Dictionary<(BannerEmblem Emblem, float Size), ArrayMesh> EmblemMeshes = new();
    private static readonly HashSet<PieceSilhouette> ReportedFallbacks = new();

    private static readonly Color OutlineInk = Color.Color8(28, 24, 30);

    // Cartoon emblems sit on the faction color itself. The shared cream ink vanishes on light faction colors
    // (gold), so those get a dark ink instead; the threshold sits between gold (luma 0.67) and the other three (~0.39).
    private static readonly Color DarkEmblemInk = Color.Color8(58, 40, 24);
    private const float LightFactionLuma = 0.55f;

    private static readonly CylinderMesh FootMesh = new()
    {
        BottomRadius = 0.36f, TopRadius = 0.35f, Height = 0.042f, RadialSegments = 10,
    };

    private static readonly CylinderMesh EnamelBandMesh = new()
    {
        BottomRadius = 0.345f, TopRadius = 0.325f, Height = 0.05f, RadialSegments = 10,
    };

    private static readonly CylinderMesh UpperLipMesh = new()
    {
        BottomRadius = 0.326f, TopRadius = 0.31f, Height = 0.022f, RadialSegments = 10,
    };

    private static readonly CylinderMesh SealBackMesh = new()
    {
        BottomRadius = 0.151f, TopRadius = 0.151f, Height = 0.006f, RadialSegments = 12,
    };

    private static readonly SphereMesh StudMesh = new()
    {
        Radius = 0.023f, Height = 0.046f, RadialSegments = 6, Rings = 3,
    };

    private static readonly ArrayMesh DuskPlinthMesh = Merge(
        (FootMesh, new Vector3(0f, 0.021f, 0f)),
        (SealBackMesh, new Vector3(0f, 0.116f, 0.194f)));

    private static readonly ArrayMesh EnamelPlinthMesh = Merge(
        (EnamelBandMesh, new Vector3(0f, 0.065f, 0f)));

    private static readonly ArrayMesh StonePlinthMesh = Merge(
        (UpperLipMesh, new Vector3(0f, 0.101f, 0f)));

    private static readonly ArrayMesh StudsMesh = Merge(
        (StudMesh, new Vector3(-0.263f, 0.115f, 0f)),
        (StudMesh, new Vector3(0.263f, 0.115f, 0f)),
        (StudMesh, new Vector3(0f, 0.115f, -0.263f)));

    // glb pieces stand directly on the cell (feet at y = 0) inside this thin faction-colored ring instead of
    // the plinth: outer radius 0.36, width 0.05, height 0.02. It leaves the cell center and most of the
    // territory tint visible.
    private const float FootRingOuter = 0.36f;
    private const float FootRingWidth = 0.05f;
    private const float FootRingHeight = 0.02f;

    // 24 segments x (top + outer wall) = 96 triangles; tools/blender/chibi_pieces.py counts them into the
    // per-piece body budget (RUNTIME_RING_TRIS) and refuses to export if FootRingSegments x 4 differs from it.
    private const int FootRingSegments = 24;
    private static readonly ArrayMesh FootRingMesh = RingMesh(FootRingOuter, FootRingOuter - FootRingWidth, FootRingHeight, FootRingSegments);

    // The ring shares the enamel surface but is drawn darker through a vertex-color multiplier,
    // so it reads as a faction marker rather than a second loud color block.
    private static readonly Color FootTint = new(0.68f, 0.68f, 0.68f);

    // Where the emblem goes when a glb has no anchor: small, flat on the front of the foot ring.
    private static readonly Transform3D FallbackEmblemAnchor =
        new(Basis.Identity.Scaled(Vector3.One * 0.045f), new Vector3(0f, FootRingHeight + 0.001f, FootRingOuter - (FootRingWidth / 2f)));

    private sealed record PieceTemplate(Dictionary<string, ArrayMesh> Meshes, bool Cartoon, Transform3D EmblemAnchor);

    internal static bool IsOutline(Node node) => node is MeshInstance3D && node.Name == OutlineName;

    /// <summary>Staged pieces: fade the outline with the ghosted body (semi-transparent, lighter ink).</summary>
    internal static void GhostOutline(MeshInstance3D outline)
    {
        if (outline.MaterialOverride is StandardMaterial3D material)
        {
            material.Transparency = BaseMaterial3D.TransparencyEnum.Alpha;
            material.AlbedoColor = new Color(material.AlbedoColor.Lerp(Color.Color8(243, 220, 191), 0.35f), 0.4f);
        }
    }

    internal static Node3D? TryBuild(
        PieceSilhouette silhouette, BannerEmblem emblem, Color faction, Color body, Color ink, int emphasisPercent)
    {
        string key = silhouette switch
        {
            PieceSilhouette.RoundPawn => "basic",
            PieceSilhouette.Tower => "fortress",
            PieceSilhouette.TwinOrbBar => "line",
            PieceSilhouette.Pyramid => "multiplier",
            PieceSilhouette.CrystalCluster => "synergy",
            PieceSilhouette.Scaffold => "artisan",
            PieceSilhouette.Pennant => "bannerman",
            PieceSilhouette.ChainLinks => "chain",
            PieceSilhouette.CrossedSpears => "sentry",
            PieceSilhouette.Stele => "boundary",
            _ => string.Empty,
        };
        if (key.Length == 0)
        {
            ReportFallback(silhouette, key);
            return null;
        }

        if (!Templates.TryGetValue(silhouette, out PieceTemplate? template))
        {
            // Cartoon glb first (tools/blender/chibi_pieces.py), then the hand-built .tscn.
            string chibi = $"res://parts/pieces_chibi/{key}.glb";
            string scene = $"res://parts/pieces/{key}.tscn";
            template = LoadTemplate(chibi, cartoon: true) ?? LoadTemplate(scene, cartoon: false);
            if (template is null)
            {
                ReportFallback(silhouette, $"{chibi} | {scene}");
                return null;
            }

            Templates.Add(silhouette, template);
            GD.Print($"[piece-models] 场景已加载 {silhouette}：{(template.Cartoon ? chibi : scene)}（{Templates.Count}/10）");
        }

        var piece = new Node3D { Name = "Piece" };
        if (template.Cartoon)
        {
            // The emblem sits on the piece itself (shield, flag, apron, banner, stele, plaque), slightly
            // off the surface along the anchor's normal. Unit-size mesh; the anchor's scale sets the size.
            Transform3D at = template.EmblemAnchor;
            at.Origin += at.Basis.Y.Normalized() * 0.004f;
            float luma = (0.299f * faction.R) + (0.587f * faction.G) + (0.114f * faction.B);
            Color emblemInk = luma > LightFactionLuma ? Visuals.Damp(DarkEmblemInk, Mathf.Max(emphasisPercent, 60)) : ink;
            piece.AddChild(new MeshInstance3D
            {
                Name = "Emblem",
                Mesh = EmblemMesh(emblem, 1f),
                MaterialOverride = Visuals.Flat(emblemInk),
                Transform = at,
                CastShadow = GeometryInstance3D.ShadowCastingSetting.Off,
            });
        }
        else
        {
            // The plinth's stone, enamel and metal are merged into the matching body slots.
            // This emblem remains its own surface so the HUD and 3D seal use the same geometry.
            piece.AddChild(new MeshInstance3D
            {
                Name = "Emblem",
                Mesh = EmblemMesh(emblem, 0.30f),
                MaterialOverride = Visuals.Flat(ink),
                Position = new Vector3(0f, 0.120f, 0.194f),
            });
        }

        var artBody = new Node3D { Name = "ArtBody" };
        foreach ((string slot, ArrayMesh mesh) in template.Meshes)
        {
            // BoardView.PreviewGhost edits MaterialOverride for staged pieces. The mesh is shared,
            // but its material is never shared between instances.
            if (slot == LineSlot)
            {
                artBody.AddChild(new MeshInstance3D
                {
                    Name = OutlineName,
                    Mesh = mesh,
                    MaterialOverride = OutlineMaterial(emphasisPercent),
                    CastShadow = GeometryInstance3D.ShadowCastingSetting.Off,
                });
                continue;
            }

            artBody.AddChild(new MeshInstance3D
            {
                Name = slot,
                Mesh = mesh,
                MaterialOverride = template.Cartoon
                    ? ToonMaterialFor(slot, faction, body, ink, emphasisPercent)
                    : MaterialFor(slot, faction, body, ink, emphasisPercent),
            });
        }

        piece.AddChild(artBody);
        return piece;
    }

    private static ArrayMesh EmblemMesh(BannerEmblem emblem, float size)
    {
        if (!EmblemMeshes.TryGetValue((emblem, size), out ArrayMesh? mesh))
        {
            mesh = LowPoly.EmblemMesh(emblem, size);
            EmblemMeshes.Add((emblem, size), mesh);
        }

        return mesh;
    }

    private static PieceTemplate? LoadTemplate(string path, bool cartoon)
    {
        if (!ResourceLoader.Exists(path))
        {
            return null;
        }

        PackedScene? scene = ResourceLoader.Load<PackedScene>(path);
        if (scene is null)
        {
            GD.PushWarning($"[piece-models] 无法加载 {path}");
            return null;
        }

        try
        {
            Node instance = scene.Instantiate();
            try
            {
                PieceTemplate? template = MergeScene(instance, cartoon);
                if (template is null)
                {
                    GD.PushWarning($"[piece-models] {path} 含无法识别材质槽的零件或没有零件");
                }
                else if (cartoon && template.EmblemAnchor == FallbackEmblemAnchor)
                {
                    GD.PushWarning($"[piece-models] {path} 没有 {AnchorName}，徽记放在脚下圆环前沿");
                }

                return template;
            }
            finally
            {
                instance.Free();
            }
        }
        catch (System.Exception error)
        {
            GD.PushWarning($"[piece-models] 无法合并 {path}：{error.Message}");
            return null;
        }
    }

    private static void ReportFallback(PieceSilhouette silhouette, string path)
    {
        if (ReportedFallbacks.Add(silhouette))
        {
            GD.Print($"[piece-models] 程序回退 {silhouette}：{path}");
        }
    }

    private static ArrayMesh Merge(params (Mesh Mesh, Vector3 Offset)[] parts)
    {
        var tool = new SurfaceTool();
        tool.Begin(Mesh.PrimitiveType.Triangles);
        foreach ((Mesh mesh, Vector3 offset) in parts)
        {
            tool.AppendFrom(mesh, 0, new Transform3D(Basis.Identity, offset));
        }

        return tool.Commit();
    }

    private static PieceTemplate? MergeScene(Node scene, bool cartoon)
    {
        var tools = new Dictionary<string, SurfaceTool>();
        int partCount = 0;
        Transform3D? anchor = null;
        if (!Append(scene, Transform3D.Identity, tools, ref partCount, ref anchor) || partCount == 0)
        {
            return null;
        }

        var meshes = new Dictionary<string, ArrayMesh>();
        if (cartoon)
        {
            // No plinth: a thin faction-colored ring around the feet, folded into the enamel slot (no extra draw call).
            foreach ((string slot, SurfaceTool tool) in tools)
            {
                meshes.Add(slot, slot == "Enamel" ? WithTintedPart(tool.Commit(), FootRingMesh, FootTint) : tool.Commit());
            }

            if (!meshes.ContainsKey("Enamel"))
            {
                meshes.Add("Enamel", WithTintedPart(null, FootRingMesh, FootTint));
            }

            return new PieceTemplate(meshes, cartoon, anchor ?? FallbackEmblemAnchor);
        }

        // .tscn pieces: the same shared plinth for all ten silhouettes. Fold it into the body
        // material slots so a richer base costs no additional draw calls per piece.
        AppendPart(tools, "Shade", DuskPlinthMesh);
        AppendPart(tools, "Enamel", EnamelPlinthMesh);
        AppendPart(tools, "Stone", StonePlinthMesh);
        AppendPart(tools, "Metal", StudsMesh);

        foreach ((string slot, SurfaceTool tool) in tools)
        {
            meshes.Add(slot, tool.Commit());
        }

        return new PieceTemplate(meshes, cartoon, anchor ?? FallbackEmblemAnchor);
    }

    /// <summary>
    /// Flat annulus standing on y = 0: top face and outer wall only. No bottom (it sits on the cell) and no
    /// inner wall (0.02 high, seen from 60° above it is under a pixel, and the triangles count against the
    /// body budget). Godot treats clockwise triangles as front faces.
    /// </summary>
    private static ArrayMesh RingMesh(float outer, float inner, float height, int segments)
    {
        var vertices = new List<Vector3>();
        var normals = new List<Vector3>();
        Vector3 up = Vector3.Up * height;
        for (int i = 0; i < segments; i++)
        {
            float a0 = Mathf.Tau * i / segments;
            float a1 = Mathf.Tau * (i + 1) / segments;
            var d0 = new Vector3(Mathf.Cos(a0), 0f, Mathf.Sin(a0));
            var d1 = new Vector3(Mathf.Cos(a1), 0f, Mathf.Sin(a1));
            Vector3 outerTop0 = (d0 * outer) + up;
            Vector3 outerTop1 = (d1 * outer) + up;
            Vector3 innerTop0 = (d0 * inner) + up;
            Vector3 innerTop1 = (d1 * inner) + up;
            Quad(outerTop0, outerTop1, innerTop0, innerTop1, Vector3.Up, Vector3.Up, Vector3.Up, Vector3.Up);
            Quad(outerTop0, d0 * outer, outerTop1, d1 * outer, d0, d0, d1, d1);
        }

        var arrays = new global::Godot.Collections.Array();
        arrays.Resize((int)Mesh.ArrayType.Max);
        arrays[(int)Mesh.ArrayType.Vertex] = vertices.ToArray();
        arrays[(int)Mesh.ArrayType.Normal] = normals.ToArray();
        var mesh = new ArrayMesh();
        mesh.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles, arrays);
        return mesh;

        // Two triangles (a, b, c) and (c, b, d), with per-vertex normals in the same order.
        void Quad(Vector3 a, Vector3 b, Vector3 c, Vector3 d, Vector3 na, Vector3 nb, Vector3 nc, Vector3 nd)
        {
            vertices.AddRange([a, b, c, c, b, d]);
            normals.AddRange([na, nb, nc, nc, nb, nd]);
        }
    }

    /// <summary>
    /// One surface holding <paramref name="body"/> (vertex color white) followed by <paramref name="extra"/>
    /// (vertex color <paramref name="tint"/>); the toon enamel material multiplies albedo by vertex color.
    /// </summary>
    private static ArrayMesh WithTintedPart(ArrayMesh? body, Mesh extra, Color tint)
    {
        var vertices = new List<Vector3>();
        var normals = new List<Vector3>();
        var colors = new List<Color>();
        var indices = new List<int>();
        if (body is not null)
        {
            Add(body.SurfaceGetArrays(0), Colors.White);
        }

        Add(extra.SurfaceGetArrays(0), tint);
        var arrays = new global::Godot.Collections.Array();
        arrays.Resize((int)Mesh.ArrayType.Max);
        arrays[(int)Mesh.ArrayType.Vertex] = vertices.ToArray();
        arrays[(int)Mesh.ArrayType.Normal] = normals.ToArray();
        arrays[(int)Mesh.ArrayType.Color] = colors.ToArray();
        arrays[(int)Mesh.ArrayType.Index] = indices.ToArray();
        var mesh = new ArrayMesh();
        mesh.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles, arrays);
        return mesh;

        void Add(global::Godot.Collections.Array surface, Color color)
        {
            int start = vertices.Count;
            Vector3[] v = surface[(int)Mesh.ArrayType.Vertex].AsVector3Array();
            Vector3[] n = surface[(int)Mesh.ArrayType.Normal].AsVector3Array();
            int[] i = surface[(int)Mesh.ArrayType.Index].AsInt32Array();
            vertices.AddRange(v);
            normals.AddRange(n.Length == v.Length ? n : Enumerable.Repeat(Vector3.Up, v.Length));
            colors.AddRange(Enumerable.Repeat(color, v.Length));
            indices.AddRange(i.Length > 0 ? i.Select(k => start + k) : Enumerable.Range(start, v.Length));
        }
    }

    private static void AppendPart(Dictionary<string, SurfaceTool> tools, string slot, Mesh mesh)
    {
        if (!tools.TryGetValue(slot, out SurfaceTool? tool))
        {
            tool = new SurfaceTool();
            tool.Begin(Mesh.PrimitiveType.Triangles);
            tools.Add(slot, tool);
        }

        tool.AppendFrom(mesh, 0, Transform3D.Identity);
    }

    private static bool Append(Node node, Transform3D parent,
        Dictionary<string, SurfaceTool> tools, ref int partCount, ref Transform3D? anchor)
    {
        Transform3D transform = node is Node3D spatial ? parent * spatial.Transform : parent;
        if (node is MeshInstance3D { Mesh: { } mesh } instance)
        {
            string? slot = SlotOf(instance.Name.ToString());
            if (slot is null || mesh.GetSurfaceCount() == 0)
            {
                return false;
            }

            for (int surface = 0; surface < mesh.GetSurfaceCount(); surface++)
            {
                if (!tools.TryGetValue(slot, out SurfaceTool? tool))
                {
                    tool = new SurfaceTool();
                    tool.Begin(Mesh.PrimitiveType.Triangles);
                    tools.Add(slot, tool);
                }

                tool.AppendFrom(mesh, surface, transform);
            }

            partCount++;
        }
        else if (node is Node3D && node.Name == AnchorName)
        {
            anchor = transform;
        }

        foreach (Node child in node.GetChildren())
        {
            if (!Append(child, transform, tools, ref partCount, ref anchor))
            {
                return false;
            }
        }

        return true;
    }

    private static string? SlotOf(string name)
    {
        int split = name.IndexOf('_');
        if (split <= 0)
        {
            return null;
        }

        return name[..split] switch
        {
            "Stone" => "Stone",
            "Shade" => "Shade",
            "Metal" => "Metal",
            "Enamel" => "Enamel",
            "Cloth" => "Cloth",
            "Crystal" => "Crystal",
            "Ink" => "Ink",
            "Line" => LineSlot,
            _ => null,
        };
    }

    private static StandardMaterial3D MaterialFor(
        string slot, Color faction, Color body, Color ink, int emphasisPercent)
    {
        Color color = slot switch
        {
            "Stone" => body.Lerp(Visuals.Damp(Color.Color8(193, 179, 158), emphasisPercent), 0.58f),
            "Shade" => Visuals.Damp(Color.Color8(92, 82, 91), emphasisPercent),
            "Metal" => Visuals.Damp(Color.Color8(177, 145, 91), emphasisPercent),
            "Enamel" => faction,
            "Cloth" => faction.Lerp(Visuals.Damp(Color.Color8(207, 185, 163), emphasisPercent), 0.12f),
            "Crystal" => body.Lerp(Visuals.Damp(Color.Color8(166, 190, 199), emphasisPercent), 0.34f),
            "Ink" => ink,
            _ => throw new System.ArgumentOutOfRangeException(nameof(slot), slot, "Unknown piece material slot."),
        };
        float roughness = slot switch
        {
            "Metal" => 0.70f,
            "Enamel" => 0.68f,
            "Crystal" => 0.58f,
            _ => 0.88f,
        };
        return Visuals.Matte(color, roughness);
    }

    /// <summary>
    /// Cartoon palette for glb pieces: two-step toon diffuse, saturated faction color, dark blue-grey steel
    /// (one step darker than v2's first pass so it never washes out to white next to the gold faction's
    /// crests in strong light), wood / leather for Cloth, faction-tinted crystal.
    /// </summary>
    private static StandardMaterial3D ToonMaterialFor(
        string slot, Color faction, Color body, Color ink, int emphasisPercent)
    {
        Color color = slot switch
        {
            "Stone" => Visuals.Damp(Color.Color8(204, 194, 180), emphasisPercent).Lerp(faction, 0.10f),
            "Shade" => Visuals.Damp(Color.Color8(70, 62, 76), emphasisPercent),
            "Metal" => Visuals.Damp(Color.Color8(128, 140, 160), emphasisPercent),
            "Enamel" => Vivid(faction),
            "Cloth" => Visuals.Damp(Color.Color8(160, 106, 64), emphasisPercent),
            "Crystal" => Vivid(faction).Lerp(Colors.White, 0.42f),
            "Ink" => ink,
            _ => throw new System.ArgumentOutOfRangeException(nameof(slot), slot, "Unknown piece material slot."),
        };
        var material = new StandardMaterial3D
        {
            AlbedoColor = color,
            Roughness = 0.22f,
            Metallic = 0f,
            DiffuseMode = BaseMaterial3D.DiffuseModeEnum.Toon,
            SpecularMode = slot is "Metal" or "Crystal"
                ? BaseMaterial3D.SpecularModeEnum.Toon
                : BaseMaterial3D.SpecularModeEnum.Disabled,
        };
        if (slot == "Enamel")
        {
            // Foot ring darkening (see FootTint); every other enamel vertex is white.
            material.VertexColorUseAsAlbedo = true;
            material.VertexColorIsSrgb = true;
        }

        if (slot == "Crystal")
        {
            material.EmissionEnabled = true;
            material.Emission = color;
            material.EmissionEnergyMultiplier = 0.18f;
        }

        return material;
    }

    private static Color Vivid(Color color)
    {
        color.ToHsv(out float h, out float s, out float v);
        return Color.FromHsv(h, Mathf.Min(1f, s * 1.12f), Mathf.Min(1f, v * 1.06f), color.A);
    }

    private static StandardMaterial3D OutlineMaterial(int emphasisPercent) => new()
    {
        AlbedoColor = Visuals.Damp(OutlineInk, Mathf.Max(emphasisPercent, 60)),
        ShadingMode = BaseMaterial3D.ShadingModeEnum.Unshaded,
        CullMode = BaseMaterial3D.CullModeEnum.Front,
    };
}
